/* Объявление */
:root {
  --primary: #0066cc;
  --spacing: 16px;
}

/* Использование */
.btn {
  background: var(--primary);
  padding: var(--spacing);
}

/* Если --text-color не объявлена, будет #333 */
.element {
  color: var(--text-color, #333);
}

/* Fallback может быть другим var() */
.element {
  color: var(--text-color, var(--primary, #000));
}

:root {
  --primary: blue;
}

.card {
  --primary: green; /* переопределение для .card и его детей */
  color: var(--primary); /* green */
}

.card .title {
  color: var(--primary); /* green — наследует от .card */
}

/* Светлая тема (по умолчанию) */
:root {
  --bg: #ffffff;
  --text: #1a1a1a;
  --border: #e0e0e0;
  --card-bg: #f8f9fa;
}

/* Тёмная тема */
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1a1a2e;
    --text: #e0e0e0;
    --border: #333333;
    --card-bg: #16213e;
  }
}

/* Использование */
body {
  background: var(--bg);
  color: var(--text);
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border);
}

.container {
  padding: var(--space-md);
}

.btn {
  padding: var(--space-sm) var(--space-lg);
}

.card {
  margin-bottom: var(--space-lg);
  padding: var(--space-xl);
}

/* Базовая кнопка */
.btn {
  --btn-bg: var(--color-primary);
  --btn-padding: var(--space-sm) var(--space-md);
  background: var(--btn-bg);
  padding: var(--btn-padding);
}

/* Крупная кнопка */
.btn-lg {
  --btn-padding: var(--space-md) var(--space-xl);
  font-size: var(--font-size-lg);
}

/* Опасная кнопка */
.btn-danger {
  --btn-bg: var(--color-danger);
}
